  async function openLevelUp(){state.levelStage='choices';const classes=E.classes(state.character),all=Object.keys(E.CLASSES),eligible=all;const selected=classes[0].name,info=E.levelInfo(state.character,selected);$('levelBody').innerHTML=levelChoiceHtml(eligible,info);$('levelNext').textContent='Review Changes';$('levelNext').onclick=reviewLevelUp;$('levelDialog').showModal();bindLevelChoice();}
  function levelChoiceHtml(classes,info){return `<div class="form-grid"><label>Choose a Class<select id="levelClass">${classes.map(name=>`<option ${name===info.className?'selected':''}>${name}</option>`).join('')}</select></label><label>Hit Point Increase<select id="hpMode"><option value="average">Fixed Average for d${info.hitDie}</option><option value="roll">Roll d${info.hitDie} in App</option><option value="physical">Use Physical d${info.hitDie}</option></select></label><label id="physicalWrap" class="hidden">Physical Die Result<input id="physicalRoll" type="number" min="1" max="${info.hitDie}"></label><div id="subclassWrap" class="${info.requiresSubclass?'':'hidden'}"><label>Choose Subclass<select id="levelSubclass">${info.subclasses.map(x=>`<option>${esc(x)}</option>`).join('')}</select></label></div><div id="asiWrap" class="${info.asi?'':'hidden'}"><label>Level Choice<select id="asiType"><option value="ability">Ability Score Improvement (+2)</option><option value="feat">Choose a Feat</option></select></label><label id="abilityWrap">Ability<select id="asiAbility">${E.ABILITIES.map(x=>`<option>${x}</option>`).join('')}</select></label><label id="levelFeatWrap" class="hidden">Feat<select id="levelFeat"><option>Loading feats…</option></select></label><div id="levelFeatDescription" class="panel wide">Choose a feat to see its description.</div></div></div><div class="level-summary"><p><strong>${esc(info.className)} Level ${info.nextClassLevel}</strong></p><p>Hit Die: d${info.hitDie}</p><p>Features: ${esc(info.features.join(', ')||'Class progression and derived values')}</p>${info.requiresSubclass?'<p>A subclass must be selected at this level.</p>':''}${info.asi?'<p>This level includes an Ability Score Improvement or feat.</p>':''}</div>`;}
  function bindLevelChoice(){const update=()=>{const info=E.levelInfo(state.character,$('levelClass').value);$('levelBody').innerHTML=levelChoiceHtml(Object.keys(E.CLASSES),info);bindLevelChoice();};$('levelClass').onchange=update;$('hpMode').onchange=()=> $('physicalWrap').classList.toggle('hidden',$('hpMode').value!=='physical');if($('asiType'))$('asiType').onchange=()=>{const feat=$('asiType').value==='feat';$('abilityWrap').classList.toggle('hidden',feat);$('levelFeatWrap').classList.toggle('hidden',!feat);$('levelFeatDescription').classList.toggle('hidden',!feat);if(feat)populateLevelFeats();};}
  async function populateLevelFeats(){const data=await reference('feats'),select=$('levelFeat');select.innerHTML=data.records.map(f=>`<option>${esc(f.name)}</option>`).join('');const update=()=>{$('levelFeatDescription').textContent=data.records.find(f=>f.name===select.value)?.description||'No description available.';};select.onchange=update;update();}
  function currentLevelChoice(){return{className:$('levelClass').value,hpMode:$('hpMode').value,physicalRoll:Number($('physicalRoll')?.value||0),subclass:$('levelSubclass')?.value||'',asiType:$('asiType')?.value||'',ability:$('asiAbility')?.value||'',feat:$('levelFeat')?.value||''};}
  async function reviewLevelUp(){try{const choice=currentLevelChoice(),info=E.levelInfo(state.character,choice.className);let feat=null;if(info.asi&&choice.asiType==='feat'){const data=await reference('feats');feat=data.records.find(f=>f.name===choice.feat);}const preview=clone(state.character),result=E.applyLevelUp(preview,choice,feat);state.pendingLevel={choice,feat,result,preview};$('levelBody').innerHTML=`<div class="level-summary"><h3>Review Every Change</h3><p><strong>Total Level:</strong> ${state.character.level} → ${result.totalLevel}</p><p><strong>${esc(choice.className)} Level:</strong> ${result.classLevel}</p><p><strong>Hit Points:</strong> ${state.character.max_hp} → ${preview.max_hp} (+${result.hpGain}; die result ${result.dieRoll})</p>${result.subclass?`<p><strong>Subclass:</strong> ${esc(result.subclass)}</p>`:''}<p><strong>New Features:</strong> ${esc(result.features.join(', ')||'None at this level')}</p>${feat?`<p><strong>Feat:</strong> ${esc(feat.name)}</p><p>${esc(feat.description||'')}</p>`:''}<p><strong>Proficiency:</strong> ${signed(state.character.derived.proficiency_bonus)} → ${signed(preview.derived.proficiency_bonus)}</p><p><strong>Spell Slots:</strong> ${esc(JSON.stringify(state.character.spell_slots_max||{}))} → ${esc(JSON.stringify(preview.spell_slots_max||{}))}</p></div>`;$('levelNext').textContent='Confirm';$('levelNext').onclick=confirmLevelUp;}catch(error){toast(error.message,true);}}
  async function confirmLevelUp(){state.character=state.pendingLevel.preview;await save(`Leveled up to ${state.character.level}`);$('levelDialog').close();renderCharacter();toast(`Level ${state.character.level} reached.`);}

  function applyTabSearch(){const q=$('tabSearch').value.trim().toLowerCase();document.querySelectorAll('#tabContent tbody tr,#tabContent .record,#tabContent .panel').forEach(el=>{el.hidden=!!q&&!el.textContent.toLowerCase().includes(q);});}
  function globalSearch(){const q=$('globalSearch').value.trim().toLowerCase();if(q.length<2){$('globalResults').innerHTML=empty('Type at least two letters','Searches every character tab.');return;}const results=[];const c=state.character;const add=(tab,label,text)=>{if(`${label} ${text}`.toLowerCase().includes(q))results.push({tab,label,text:String(text).slice(0,180)});};(c.inventory||[]).forEach(x=>add('inventory',x.name,x.notes||''));(c.feature_records||[]).forEach(x=>add('features-feats',x.name,x.description||''));(c.spells||[]).forEach(x=>{const n=typeof x==='string'?x:x.name,s=spellRecord(n);add('spells',n,s.description||'');});(c.session_notes||[]).forEach(x=>add('details',x.title,x.body));Object.entries(c).forEach(([k,v])=>{if(typeof v==='string')add('details',title(k),v);});$('globalResults').innerHTML=results.length?results.map((r,i)=>`<button class="search-result" data-result="${i}"><strong>${esc(r.label)}</strong><span>${esc(TABS.find(x=>x[0]===r.tab)?.[1]||r.tab)} · ${esc(r.text)}</span></button>`).join(''):empty('No results','Try another phrase.');document.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>{const r=results[Number(b.dataset.result)];state.activeTab=r.tab;$('searchDialog').close();renderTabs();renderActiveTab().then(()=>{$('tabSearch').value=q;applyTabSearch();document.querySelector('#tabContent [data-searchable],#tabContent tbody tr')?.classList.add('search-hit');});});}

  function downloadSheet(){if(!state.character)return;const win=open('','_blank');if(!win)return toast('Allow pop-ups to open the printable sheet.',true);win.document.write(`<!doctype html><title>${esc(preferredName(state.character))} Character Sheet</title><style>@page{size:letter;margin:.35in}*{box-sizing:border-box}body{margin:0;background:#eee;color:#231d18;font:12px Georgia,serif}.paper-page{width:8.5in;min-height:10.3in;margin:20px auto;padding:.35in;background:#f6ead2;border:1px solid #9e8368;page-break-after:always}.paper-head{display:flex;justify-content:space-between;border-bottom:3px solid #772f37;padding-bottom:12px}.paper-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:8px;margin:14px 0}.paper-cell{border:1px solid #9e8368;padding:10px;text-align:center}.paper-cell strong{display:block;font-size:22px}.paper-columns{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.paper-columns section,.paper-list section{border:1px solid #b79c80;padding:10px;margin:8px 0}.wide{grid-column:span 2}.data-table{width:100%;border-collapse:collapse}.data-table td,.data-table th{border:1px solid #9e8368;padding:6px;text-align:left}.paper-currency{display:flex;gap:20px;margin-top:20px}footer{position:absolute;bottom:.25in;right:.35in;color:#765}.paper-page{position:relative}button{position:fixed;right:20px;top:20px;padding:12px 18px}@media print{body{background:none}.paper-page{margin:0;border:0}button{display:none}}</style>${sheetPages(state.character)}<button onclick="print()">Download / Print PDF</button>`);win.document.close();}

  function randomCharacter(){const names=['Aeris Silverhand','Kael Dawnforge','Nyx Nightwind','Vexa Whisperwind'],className=Object.keys(E.CLASSES)[Math.floor(Math.random()*Object.keys(E.CLASSES).length)],scores=Object.fromEntries(E.ABILITIES.map(a=>[a,8+Math.floor(Math.random()*11)]));const info=E.CLASSES[className],c={id:E.uid(),name:names[Math.floor(Math.random()*names.length)],race:'Human',background:'Adventurer',alignment:'True Neutral',character_class:className,classes:[{name:className,level:1,subclass:info.sub===1?info.subs[0]:''}],subclass:info.sub===1?info.subs[0]:'',level:1,ability_scores:scores,base_ability_scores:clone(scores),current_hp:info.die+E.mod(scores.constitution),max_hp:info.die+E.mod(scores.constitution),temporary_hp:0,speed:30,movement:{walk:30,swim:0,fly:0,long_jump:scores.strength,high_jump:Math.max(0,3+E.mod(scores.strength))},experience:0,conditions:[],inventory:[],currency:{cp:0,sp:0,ep:0,gp:0,pp:0},group_funds:{cp:0,sp:0,ep:0,gp:0,pp:0},group_items:{'Bag of Holding':[],'Refridge-A-Bag':[]},feature_records:[],spells:[],prepared_spells:[],spell_metadata:{},spell_slots_max:{},spell_slots_used:{},active_spells:[],saving_throw_proficiencies:[],skill_proficiencies:[],created_at:new Date().toISOString(),general_notes:'',session_notes:[]};return E.recalc(c);}

  function applyPreferences(input=null){const p=input||JSON.parse(localStorage.getItem('dndPreferences')||'{}');document.body.dataset.theme=p.theme||'midnight';document.documentElement.style.setProperty('--scale',p.scale||1);document.documentElement.style.setProperty('--glass',String((p.opacity??78)/100));document.documentElement.style.setProperty('--blur',`${p.blur??22}px`);if(p.accent)document.documentElement.style.setProperty('--accent',p.accent);else document.documentElement.style.removeProperty('--accent');if(p.main){document.documentElement.style.setProperty('--main',p.main);document.documentElement.style.setProperty('--surface2',p.main);}else{document.documentElement.style.removeProperty('--main');document.documentElement.style.removeProperty('--surface2');}document.body.classList.toggle('no-frost',p.frost===false);document.body.classList.toggle('reduce-transparency',p.reduceTransparency===true);document.body.classList.toggle('square',p.rounded===false);$('themeControl').value=p.theme||'midnight';$('accentControl').value=p.accent||'';$('mainControl').value=p.main||'';$('scaleControl').value=String(p.scale||1);$('opacityControl').value=p.opacity??78;$('opacityValue').textContent=`${p.opacity??78}%`;$('blurControl').value=p.blur??22;$('blurValue').textContent=`${p.blur??22}px`;$('frostControl').checked=p.frost!==false;$('transparencyControl').checked=p.reduceTransparency===true;$('roundedControl').checked=p.rounded!==false;}
  function colorValue(value){const names={blue:'#6aa8ff',red:'#ff6b7b',crimson:'#9f263d',yellow:'#f5ca68',green:'#55d6a1',purple:'#a884ff',orange:'#ff9a70',pink:'#ee7dcc',teal:'#54ced2',navy:'#16243b',obsidian:'#10131b',black:'#050608',white:'#f5f7ff',gray:'#6e788b',grey:'#6e788b'};if(!value)return'';if(names[value.toLowerCase()])return names[value.toLowerCase()];if(/^#[0-9a-f]{6}$/i.test(value))return value;throw new Error('Use a supported color name or a six-digit hex code beginning with #.');}

  // Public session editor and merge review remain isolated from the private workspace.
  function renderPublic(){const c=E.recalc(state.publicCharacter);if(!c)return;$('publicCharacterName').textContent=preferredName(c);$('publicSessionStatus').textContent=`Public revision ${state.publicSession?.public_revision||0} · ${state.publicSession?.pending_changes||0} pending changes`;const fields=[['current_hp','Current HP'],['temporary_hp','Temporary HP'],['exhaustion','Exhaustion'],['death_save_successes','Death Save Successes'],['death_save_failures','Death Save Failures'],['hit_dice_used','Hit Dice Used']];$('publicQuickFields').innerHTML=fields.map(([k,l])=>field(l,k,c[k]??'','number')).join('')+`<label class="check"><input name="inspiration" type="checkbox" ${c.inspiration?'checked':''}> Inspiration</label>`;$('publicAbilities').innerHTML=E.ABILITIES.map(a=>abilityCard(a,c.ability_scores?.[a]??10,c.derived?.modifiers?.[a]??0,'read-only')).join('');$('publicProficiencies').innerHTML=`<div><h4>Saving Throws</h4>${E.ABILITIES.map(a=>`<p><span class="read-check ${c.saving_throw_proficiencies?.includes(a)?'on':''}"></span>${title(a)} <b>${signed(c.derived?.saving_throws?.[a])}</b></p>`).join('')}</div><div><h4>Skills</h4>${Object.keys(E.SKILLS).sort().map(s=>`<p><span class="read-check ${c.skill_proficiencies?.includes(s)?'on':''}"></span>${esc(s)} <b>${signed(c.derived?.skills?.[s])}</b></p>`).join('')}</div>`;const active=new Set(c.conditions||[]);$('publicConditions').innerHTML=CONDITIONS.map(x=>`<label class="check-row"><input data-public-condition="${esc(x)}" type="checkbox" ${active.has(x)?'checked':''}>${x}</label>`).join('');$('publicSpellSlots').innerHTML=Object.keys(c.spell_slots_max||{}).map(l=>field(`Level ${l} Used`,`slot-${l}`,c.spell_slots_used?.[l]||'','number',`min="0" max="${c.spell_slots_max[l]}"`)).join('')||'<p class="muted">No spell slots.</p>';$('publicActiveSpells').innerHTML=table(['Spell','Level','Turns'],(c.active_spells||[]).map((s,i)=>[esc(s.name),esc(s.cast_level||'Unknown'),`<input data-public-active="${i}" type="number" value="${s.turns_remaining||0}">`]));$('publicInventory').innerHTML=table(['Item','Qty','Equipped','Attuned','Notes'],(c.inventory||[]).map((i,n)=>[esc(itemName(i)),`<input data-public-item="${n}" data-key="quantity" type="number" value="${i.quantity??1}">`,`<input data-public-item="${n}" data-key="equipped" type="checkbox" ${i.equipped?'checked':''}>`,`<input data-public-item="${n}" data-key="attuned" type="checkbox" ${i.attuned?'checked':''}>`,`<input data-public-item="${n}" data-key="notes" value="${esc(i.notes||'')}">`]));$('publicCurrency').innerHTML=COINS.map(x=>field(x.toUpperCase(),`coin-${x}`,c.currency?.[x]||'','number')).join('');$('publicGroupFunds').innerHTML=COINS.map(x=>field(x.toUpperCase(),`fund-${x}`,c.group_funds?.[x]||'','number')).join('');$('publicFeatures').innerHTML=table(['Feature','Used','Maximum'],(c.feature_records||[]).filter(r=>r.max_uses).map(r=>[esc(r.name),`<input data-public-feature="${c.feature_records.indexOf(r)}" type="number" value="${r.uses_used||0}">`,r.max_uses]));$('publicNotes').value=c.general_notes||'';}
  function publicForm(){const c=clone(state.publicCharacter);document.querySelectorAll('#publicQuickFields [name]').forEach(x=>c[x.name]=x.type==='checkbox'?x.checked:Number(x.value||0));c.conditions=[...document.querySelectorAll('[data-public-condition]:checked')].map(x=>x.dataset.publicCondition);document.querySelectorAll('[data-public-active]').forEach(x=>c.active_spells[Number(x.dataset.publicActive)].turns_remaining=Number(x.value||0));document.querySelectorAll('[data-public-item]').forEach(x=>{const item=c.inventory[Number(x.dataset.publicItem)];item[x.dataset.key]=x.type==='checkbox'?x.checked:x.type==='number'?Number(x.value||0):x.value;});c.currency||={};c.group_funds||={};COINS.forEach(x=>{c.currency[x]=Number(document.querySelector(`[name="coin-${x}"]`).value||0);c.group_funds[x]=Number(document.querySelector(`[name="fund-${x}"]`).value||0);});document.querySelectorAll('[data-public-feature]').forEach(x=>c.feature_records[Number(x.dataset.publicFeature)].uses_used=Number(x.value||0));c.general_notes=$('publicNotes').value;return E.recalc(c);}
  async function restorePublic(){if(!state.publicToken)return showPublicLogin();try{const r=await api('publicSession',{publicToken:state.publicToken});state.publicCharacter=r.character;state.publicSession=r.session;showPublic();renderPublic();}catch(e){state.publicToken='';sessionStorage.removeItem(publicStorageKey);showPublicLogin(e.message);}}
  async function loadShareSessions(){state.shareSessions=await api('listPublicSessions',{characterId:state.character.id});$('shareSessionList').innerHTML=state.shareSessions.length?state.shareSessions.map(s=>`<article class="record"><strong>${s.enabled?'Active':'Closed'} Public Session</strong><p>${esc(s.created_at)} · ${s.pending_changes} pending · ${s.merged_changes} merged</p><div class="section-actions">${button('Review Changes','share-review',s.id)}${s.enabled?button('Disable Access','share-disable',s.id):''}</div></article>`).join(''):empty('No sharing sessions','Create one when a friend needs the character.');bindContentActions($('shareSessionList'));}
  async function openMerge(id){state.mergeReview=await api('publicMergeReview',{sessionId:id});const cats=Object.keys(state.mergeReview.categories||{});state.mergeCategory=cats[0]||'';$('mergeCategory').innerHTML=cats.map(c=>`<option>${esc(c)}</option>`).join('');renderMerge();$('mergeDialog').showModal();}
  function renderMerge(){const rows=state.mergeReview?.categories?.[state.mergeCategory]||[];$('mergeEventList').innerHTML=rows.length?rows.map(e=>`<label class="merge-event"><input data-merge-event="${e.id}" type="checkbox"><span><strong>${esc(title(e.path))}</strong><small>${esc(e.editor)} · ${esc(e.created_at)}</small><span>${esc(JSON.stringify(e.before))} → ${esc(JSON.stringify(e.after))}</span></span></label>`).join(''):empty('No pending changes','Everything is already merged.');document.querySelectorAll('[data-merge-event]').forEach(x=>x.onchange=updateMergeCount);$('mergeHistory').innerHTML=(state.mergeReview?.merge_batches||[]).map(b=>`<p>${esc(b.created_at)} · ${(b.event_ids||[]).length} applied</p>`).join('');updateMergeCount();}
