  $('loginForm').onsubmit=async e=>{e.preventDefault();try{const s=await api('login',{email:$('email').value,password:$('password').value});state.token=s.token;sessionStorage.setItem('dndSession',state.token);$('password').value='';showLibrary();await loadLibrary();}catch(error){showLogin(error.message);}};
  $('libraryBack').onclick=async()=>{showLibrary();await loadLibrary(state.character?.id||'');};$('menuButton').onclick=()=>toggleSiteNav(true);$('closeSiteNav').onclick=() => toggleSiteNav(false);$('siteNavScrim').onclick=()=>toggleSiteNav(false);$('preferencesButton').onclick=()=>$('settingsDialog').showModal();$('globalSearchButton').onclick=()=>{$('globalSearch').value='';$('globalResults').innerHTML=empty('Search the whole character','Enter a feature, spell, item, note, or detail.');$('searchDialog').showModal();setTimeout(()=>$('globalSearch').focus(),50);};$('globalSearch').oninput=globalSearch;$('tabSearch').oninput=()=>{if(['magic-items','class-info','roll20','magic-spells'].includes(state.activeTab)){clearTimeout(state.searchTimer);state.searchTimer=setTimeout(renderActiveTab,350);}else applyTabSearch();};
  $('librarySearch').oninput=()=>{renderLibrary();renderLibraryPreview();};$('selectAll').onclick=()=>{state.selected=new Set(filteredCharacters().map(c=>c.id));renderLibrary();renderLibraryPreview();};$('clearSelection').onclick=()=>{state.selected.clear();renderLibrary();renderLibraryPreview();};$('openCharacter').onclick=()=>openCharacter();$('downloadCharacter').onclick=async()=>{await selectedCharacter();downloadSheet();};
