  $('shareButton').onclick=()=>{$('shareSessionList').innerHTML='<p class="muted">Loading sharing status…</p>';$('shareDialog').showModal();loadShareSessions().catch(error=>$('shareSessionList').innerHTML=`<div class="error-state"><strong>Sharing status could not be loaded.</strong><p>${esc(error.message)}</p><button class="button" type="button" data-action="share-retry">Retry</button></div>`);};$('createShareButton').onclick=async()=>{try{const r=await api('createPublicSession',{characterId:state.character.id,pin:$('newSharePin').value});$('newSharePin').value='';const url=new URL(`?share=${r.share_token}`,location.href).href;$('newShareResult').innerHTML=`<p>Public session enabled.</p><div class="control-row"><input id="shareUrl" value="${esc(url)}" readonly><button id="copyShareUrl" class="button" type="button">Copy Link</button><a class="button" href="${esc(url)}" target="_blank" rel="noreferrer">Open</a></div>`;$('copyShareUrl').onclick=async()=>{await navigator.clipboard.writeText(url);toast('Share link copied.');};await loadShareSessions();}catch(e){toast(e.message,true);}};
  $('publicLoginForm').onsubmit=async e=>{e.preventDefault();try{const r=await api('publicOpen',{shareToken:state.shareToken,pin:$('publicPin').value,editorName:$('publicEditorName').value});state.publicToken=r.public_token;sessionStorage.setItem(publicStorageKey,state.publicToken);state.publicCharacter=r.character;state.publicSession=r.session;showPublic();renderPublic();}catch(error){showPublicLogin(error.message);}};$('publicSaveButton').onclick=async()=>{try{const c=publicForm(),r=await api('publicSave',{publicToken:state.publicToken,character:c,changeNote:$('publicChangeNote').value});state.publicCharacter=r.character;state.publicSession=r.session;$('publicChangeNote').value='';renderPublic();$('publicSaveStatus').textContent=`${r.changesCreated||0} change-log item(s) saved.`;}catch(e){$('publicSaveStatus').textContent=e.message;}};
  $('mergeCategory').onchange=e=>{state.mergeCategory=e.target.value;renderMerge();};$('selectMergeCategory').onchange=e=>{document.querySelectorAll('[data-merge-event]').forEach(x=>x.checked=e.target.checked);updateMergeCount();};$('mergeSelectedButton').onclick=async()=>{const ids=mergeIds();if(!ids.length)return toast('Select changes to merge.',true);const resolutions=Object.fromEntries([...document.querySelectorAll('[data-merge-resolution]')].map(x=>[x.dataset.mergeResolution,x.value]));try{const result=await api('mergePublicChanges',{sessionId:state.mergeReview.session.id,eventIds:ids,resolutions});if(result.merged===false&&result.conflicts?.length){renderMergeConflicts(result.conflicts);toast('Choose how to resolve each private/public conflict.');return;}$('mergeConflictBox').innerHTML='';await openMerge(state.mergeReview.session.id);state.character=E.recalc(await api('getCharacter',{characterId:state.character.id}));renderCharacter();toast('Selected public changes merged.');}catch(e){toast(e.message,true);}};
  $('logoutButton').onclick=async()=>{try{await api('logout');}catch{}state.token='';sessionStorage.removeItem('dndSession');$('settingsDialog').close();showLogin();};const readPreferences=()=>({theme:$('themeControl').value,accent:colorValue($('accentControl').value.trim()),main:colorValue($('mainControl').value.trim()),scale:Number($('scaleControl').value),opacity:Number($('opacityControl').value),blur:Number($('blurControl').value),frost:$('frostControl').checked,reduceTransparency:$('transparencyControl').checked,rounded:$('roundedControl').checked});$('applySettings').onclick=e=>{e.preventDefault();try{const p=readPreferences();localStorage.setItem('dndPreferences',JSON.stringify(p));applyPreferences(p);$('settingsDialog').close();toast('Preferences saved and applied.');}catch(error){toast(error.message,true);}};['themeControl','accentControl','mainControl','scaleControl','opacityControl','blurControl','frostControl','transparencyControl','roundedControl'].forEach(id=>$(id).addEventListener('input',()=>{try{applyPreferences(readPreferences());}catch{}}));$('resetSettings').onclick=()=>{localStorage.removeItem('dndPreferences');applyPreferences({});};
  document.addEventListener('click',async e=>{const close=e.target.closest('[data-close-dialog]');if(close){e.preventDefault();close.closest('dialog')?.close();return;}const b=e.target.closest('[data-action]');if(!b||e.defaultPrevented)return;if(b.dataset.action==='share-retry')return loadShareSessions();if(b.dataset.action==='share-review')return openMerge(b.dataset.id);if(b.dataset.action==='share-disable'){if(await askConfirm('Disable public access?','The existing guest link will stop working.','Disable Access')){await api('disablePublicSession',{sessionId:b.dataset.id});await loadShareSessions();}return;}return handleAction(b.dataset.action,b.dataset.id||'');});document.addEventListener('input',e=>{if(e.target.matches('[data-sheet-zoom]'))setSheetZoom(Number(e.target.value)/100);});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.viewerExpanded){e.preventDefault();setViewerExpanded(false);}});

